diff --git a/source/standalone/request-callable-fields.ts b/source/standalone/request-callable-fields.ts
new file mode 100644
index 0000000..058a8a8
--- /dev/null
+++ b/source/standalone/request-callable-fields.ts
@@ -0,0 +1,21 @@
+type UnknownRecord = Record<string, unknown>;
+
+const isPlainObjectLike = (value: unknown): value is UnknownRecord =>
+	(typeof value === 'object' || typeof value === 'function')
+	&& value !== null
+	&& !Array.isArray(value);
+
+/**
+Get the sorted own enumerable string keys of `value` whose values are callable.
+
+Returns an empty array for `null`, primitives, and arrays. Inherited members are ignored.
+*/
+export function requestCallableFields(value: unknown): string[] {
+	if (!isPlainObjectLike(value)) {
+		return [];
+	}
+
+	return Object.keys(value)
+		.filter(key => typeof value[key] === 'function')
+		.sort();
+}
diff --git a/test/request-callable-fields.ts b/test/request-callable-fields.ts
new file mode 100644
index 0000000..2f15cbf
--- /dev/null
+++ b/test/request-callable-fields.ts
@@ -0,0 +1,55 @@
+import test from 'ava';
+import {requestCallableFields} from '../source/standalone/request-callable-fields.js';
+
+test('returns sorted own enumerable callable keys', t => {
+	const alpha = async () => {};
+
+	t.deepEqual(requestCallableFields({
+		zeta() {},
+		alpha,
+		beta: 1,
+		gamma: 'string',
+		delta: class {
+			value = 1;
+		},
+	}), ['alpha', 'delta', 'zeta']);
+});
+
+test('returns an empty array for null, primitives and arrays', t => {
+	for (const value of [null, undefined, 0, 1, '', 'foo', true, Symbol('foo'), 10n, [() => {}], []]) {
+		t.deepEqual(requestCallableFields(value), []);
+	}
+});
+
+test('gives `_onResponse` no special meaning', t => {
+	t.deepEqual(requestCallableFields({_onResponse: true}), []);
+	t.deepEqual(requestCallableFields({_onResponse() {}}), ['_onResponse']);
+	t.deepEqual(requestCallableFields({}), []);
+});
+
+test('ignores inherited members', t => {
+	const prototype = {inherited() {}};
+	const object = Object.create(prototype) as Record<string, unknown>;
+	object.own = () => {};
+
+	t.deepEqual(requestCallableFields(object), ['own']);
+	t.deepEqual(requestCallableFields(Object.create({_onResponse() {}})), []);
+});
+
+test('ignores non-enumerable and symbol keys', t => {
+	const object: Record<string | symbol, unknown> = {visible() {}};
+	Object.defineProperty(object, 'hidden', {value() {}, enumerable: false});
+	object[Symbol('symbol')] = () => {};
+
+	t.deepEqual(requestCallableFields(object), ['visible']);
+});
+
+test('ignores class prototype methods on instances', t => {
+	class Example {
+		field = () => {};
+
+		method() {}
+	}
+
+	t.deepEqual(requestCallableFields(new Example()), ['field']);
+});
